
(()=>{const url=new URL(location.href);const value=url.searchParams.get('gmail_connection');if(!value)return;url.searchParams.delete('gmail_connection');history.replaceState(null,'',url.pathname+url.search+url.hash);if(window.opener){window.opener.postMessage({type:'ama-gmail-result',success:value==='connected'},location.origin);window.close();}else{const note=document.createElement('p');note.setAttribute('role','status');note.style.cssText='position:fixed;bottom:90px;left:16px;right:16px;z-index:9999;background:#fff;padding:16px;border:1px solid #398b7b;border-radius:12px;color:#315a72';note.textContent=value==='connected'?'Gmail LD Clean connecté. Ouvrez Factures → Configuration → LD Clean, puis envoyez un test.':'Connexion Gmail non terminée. Réessayez dans Configuration avec ldclean06@gmail.com.';document.body.appendChild(note);note.addEventListener('click',()=>note.remove());}})();
